import type { ArticleMeasurementView } from "@/lib/film-article";
import type { ArticleMeasurementRef } from "@/lib/film-package";
import { trumanCanonicalScenes } from "./the-truman-show-scene-inventory";
import rawMeasurements from "./the-truman-show-master-windows.json";

/**
 * Film 001 — measured timing of the locked master.
 *
 * `the-truman-show-master-windows.json` is generated by
 * `scripts/film001-evidence-bundle/measure-master-windows.mjs --out <this path>`
 * from the derived evidence bundle of the exact viewing master
 * (SHA-256 E8543F61…B3B575, 6177.792 s). It is committed verbatim: do not
 * hand-edit it, re-run the script.
 *
 * This wrapper adds the one thing the script cannot know — which verified scene
 * each measurement falls into — and hands the article validator a resolver, so
 * an article measurement block can only quote a row that exists here.
 *
 * What the numbers are and are not:
 *
 * - `detectedTransitions` counts ffmpeg `scene` scores above 0.32 on the
 *   native-resolution stream. Threshold detection is not a shot log: a long
 *   dissolve can stay below the threshold and read as one continuous stretch.
 *   Prose built on this data must say "detected transition", never "shot".
 * - `subtitleCueStarts` counts embedded English SubRip cues whose *start* lies
 *   inside the window. Cues that straddle a boundary are not counted.
 */

type RawWindow = {
  id: string;
  label: string;
  from: number;
  to: number;
  durationSeconds: number;
  detectedTransitions: number;
  subtitleCueStarts: number;
};

type RawHold = {
  from: number;
  to: number;
  durationSeconds: number;
  subtitleCueStarts: number;
};

type RawSilence = {
  from: number;
  to: number;
  durationSeconds: number;
  detectedTransitions: number;
};

type RawMeasurements = {
  inputs: {
    masterSha256: string | null;
    durationSeconds: number;
    sceneScoreThreshold: number;
    cutsCsvSha256: string;
    subtitleSrtSha256: string;
    subtitleTrack: string;
  };
  method: {
    transition: string;
    hold: string;
    cueWindow: string;
    silence: string;
    caveat: string;
  };
  totals: {
    detectedTransitions: number;
    subtitleCues: number;
    meanSecondsBetweenTransitions: number;
    firstTransitionSeconds: number;
    lastTransitionSeconds: number;
    lastCueEndSeconds: number;
    tailAfterLastCueSeconds: number;
  };
  longestHold: RawHold;
  holds: RawHold[];
  silences: RawSilence[];
  windows: RawWindow[];
};

const measurements = rawMeasurements as RawMeasurements;

export type TrumanMeasuredWindow = RawWindow & {
  /** Verified scene containing the moment (window start / window end). */
  startSceneId: string;
  endSceneId: string;
  timecode: string;
};

export type TrumanMeasuredHold = RawHold & {
  id: string;
  startSceneId: string;
  endSceneId: string;
  timecode: string;
};

export type TrumanMeasuredSilence = RawSilence & {
  id: string;
  startSceneId: string;
  endSceneId: string;
  timecode: string;
};

/** `MM:SS` in elapsed minutes, the way the article addresses the master. */
export function formatMasterTimecode(seconds: number): string {
  const total = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(total / 60);
  return `${String(minutes).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
}

function sceneAt(seconds: number): string {
  const scene = trumanCanonicalScenes.find(
    (candidate) =>
      seconds >= candidate.startTimestampSeconds && seconds < candidate.endTimestampSeconds,
  );
  if (!scene) {
    throw new Error(`Film 001 measurement at ${seconds}s falls outside the verified scene inventory.`);
  }
  return scene.id;
}

export const trumanMasterMeasurementProvenance = measurements.inputs;
export const trumanMasterMeasurementMethod = measurements.method;
export const trumanMasterTimingTotals = measurements.totals;

export const trumanMasterWindows: TrumanMeasuredWindow[] = measurements.windows.map((window) => ({
  ...window,
  startSceneId: sceneAt(window.from),
  endSceneId: sceneAt(Math.max(window.from, window.to - 0.001)),
  timecode: formatMasterTimecode(window.from),
}));

/** Ranked longest-first, exactly as the script emitted them. */
export const trumanMasterHolds: TrumanMeasuredHold[] = measurements.holds.map((hold, index) => ({
  ...hold,
  id: `hold-${String(index + 1).padStart(2, "0")}`,
  startSceneId: sceneAt(hold.from),
  endSceneId: sceneAt(Math.max(hold.from, hold.to - 0.001)),
  timecode: formatMasterTimecode(hold.from),
}));

export const trumanMasterSilences: TrumanMeasuredSilence[] = measurements.silences.map(
  (silence, index) => ({
    ...silence,
    id: `silence-${String(index + 1).padStart(2, "0")}`,
    startSceneId: sceneAt(silence.from),
    endSceneId: sceneAt(Math.max(silence.from, silence.to - 0.001)),
    timecode: formatMasterTimecode(silence.from),
  }),
);

export type TrumanMeasuredTotals = {
  id: "master";
  detectedTransitions: number;
  subtitleCues: number;
  meanSecondsBetweenTransitions: number;
  durationSeconds: number;
};

export const trumanMasterMeasurementTotals: TrumanMeasuredTotals = {
  id: "master",
  detectedTransitions: measurements.totals.detectedTransitions,
  subtitleCues: measurements.totals.subtitleCues,
  meanSecondsBetweenTransitions: measurements.totals.meanSecondsBetweenTransitions,
  durationSeconds: measurements.inputs.durationSeconds,
};

export type TrumanMeasuredRecord =
  | TrumanMeasuredWindow
  | TrumanMeasuredHold
  | TrumanMeasuredSilence
  | TrumanMeasuredTotals;

/**
 * Resolves an article measurement reference. The article never types the
 * numbers itself: it points here and the renderer prints what the master
 * measured.
 */
export function resolveTrumanMeasurement(ref: ArticleMeasurementRef): TrumanMeasuredRecord | undefined {
  switch (ref.table) {
    case "totals":
      return ref.id === trumanMasterMeasurementTotals.id ? trumanMasterMeasurementTotals : undefined;
    case "window":
      return trumanMasterWindows.find((window) => window.id === ref.id);
    case "hold":
      return trumanMasterHolds.find((hold) => hold.id === ref.id);
    case "silence":
      return trumanMasterSilences.find((silence) => silence.id === ref.id);
  }
}

/**
 * Digit strings the master measured. Article prose may not contain any of them:
 * a measured number is printed by the renderer from this dataset, so it cannot
 * drift the way a number retyped into a sentence does.
 *
 * Small integers are excluded on purpose — they collide with ordinary prose
 * ("пять предметов", "сто минут") and carry no measurement weight here.
 */
export const trumanMeasuredDigitStrings: string[] = [
  ...new Set(
    [
      trumanMasterMeasurementTotals.detectedTransitions,
      trumanMasterMeasurementTotals.subtitleCues,
      trumanMasterMeasurementTotals.meanSecondsBetweenTransitions,
      trumanMasterMeasurementTotals.durationSeconds,
      ...trumanMasterWindows.flatMap((window) => [
        window.detectedTransitions,
        window.subtitleCueStarts,
        window.durationSeconds,
      ]),
      ...trumanMasterHolds.flatMap((hold) => [hold.durationSeconds, hold.subtitleCueStarts]),
      ...trumanMasterSilences.flatMap((silence) => [
        silence.durationSeconds,
        silence.detectedTransitions,
      ]),
    ]
      .filter((value) => (Number.isInteger(value) ? value >= 200 : String(value).length >= 4))
      .map(String),
  ),
];

/* ------------------------------------------------------------------------- *
 * Presentation layer for the article.
 *
 * Numbers are formatted here, next to the dataset that produced them, so the
 * view never sees a raw measurement it could round, retype or "improve".
 * ------------------------------------------------------------------------- */

const plural = (count: number, one: string, few: string, many: string): string => {
  const mod10 = Math.abs(count) % 10;
  const mod100 = Math.abs(count) % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return few;
  return many;
};

const groupDigits = (value: number): string => String(value).replace(/\B(?=(\d{3})+(?!\d))/g, " ");

const transitionsPhrase = (count: number): string =>
  `${groupDigits(count)} ${plural(count, "переход", "перехода", "переходов")}`;

/**
 * A subtitle cue is not a line of dialogue: one block can hold two speakers, and a
 * block with no speech can still be a cue. The count is named for what was counted.
 */
const cuesPhrase = (count: number): string =>
  `${groupDigits(count)} ${plural(count, "строка субтитров", "строки субтитров", "строк субтитров")}`;

/**
 * Detected transitions per minute of the window.
 *
 * The window table prints a count and a length; a reader should not have to divide
 * to compare two windows that are sixty-five seconds and four minutes long. The
 * rate is derived from the same measurement, so the two can never disagree, and a
 * fractional value takes the genitive singular («28,6 перехода»).
 */
const perMinute = (count: number, seconds: number): string =>
  seconds > 0 ? ((count / seconds) * 60).toFixed(1).replace(".", ",") : "—";

/** `MM:SS` without the leading zero: "2:04", "4:12". */
const duration = (seconds: number): string => {
  const total = Math.max(0, Math.round(seconds));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
};

/**
 * A window written as start–end.
 *
 * The end is derived from the rounded duration rather than formatted from the
 * raw end timestamp, so the two numbers always add up: a reader who subtracts
 * the printed times must land on the printed length, otherwise the article
 * contradicts itself in a way no test would catch.
 */
const span = (from: number, to: number): string =>
  `${formatMasterTimecode(from)}–${formatMasterTimecode(Math.floor(from) + Math.round(to - from))}`;

const WINDOW_LABELS: Record<string, string> = {
  library: "Библиотека: Труман, посетители и девушка в красном",
  // The window is 46:29–47:34, inside `truman-sc-lady-flowers-dented-beetle`: the
  // street where the same passers-by and the same dented car come round again. It is
  // not a manhunt, and the label may not say what the scene does not show.
  panic: "Повторяющиеся прохожие и помятый жук на той же улице",
  "hes-gone": "Побег и поиски: пустая кровать, город, вода",
  wall: "Стена, лестница, поиск выхода",
};

export function describeTrumanMeasurement(
  ref: ArticleMeasurementRef,
): ArticleMeasurementView | undefined {
  const record = resolveTrumanMeasurement(ref);
  if (!record) return undefined;

  if ("id" in record && record.id === "master") {
    const totals = trumanMasterMeasurementTotals;
    return {
      title: "Залоченный мастер целиком",
      primary: transitionsPhrase(totals.detectedTransitions),
      secondary: cuesPhrase(totals.subtitleCues),
      detail: `средний интервал ${totals.meanSecondsBetweenTransitions} с · ${duration(totals.durationSeconds)} экрана`,
    };
  }

  if (ref.table === "window") {
    const window = record as TrumanMeasuredWindow;
    return {
      title: WINDOW_LABELS[window.id] ?? window.label,
      primary: transitionsPhrase(window.detectedTransitions),
      secondary: cuesPhrase(window.subtitleCueStarts),
      detail: `${span(window.from, window.to)} · ${duration(window.durationSeconds)} · ${perMinute(
        window.detectedTransitions,
        window.durationSeconds,
      )} перехода в минуту`,
    };
  }

  if (ref.table === "hold") {
    const hold = record as TrumanMeasuredHold;
    return {
      title:
        hold.id === "hold-01"
          ? "Самый длинный отрезок без обнаруженного перехода"
          : hold.id === "hold-02"
            ? "Библиотека: Труман, посетители и девушка в красном"
            : "Без обнаруженного перехода",
      primary: duration(hold.durationSeconds),
      secondary: cuesPhrase(hold.subtitleCueStarts),
      detail: `${span(hold.from, hold.to)} · ни одного обнаруженного перехода`,
    };
  }

  const silence = record as TrumanMeasuredSilence;
  return {
    title: "У края нарисованного неба",
    primary: duration(silence.durationSeconds),
    secondary: transitionsPhrase(silence.detectedTransitions),
    detail: `${span(silence.from, silence.to)} · ни одной строки субтитров`,
  };
}
